#!/usr/bin/env node
/**
 * Generates src/i18n/translations/<locale>.json and index.ts from every
 * `translation` entry in Contentful (all locales), so static UI text is baked
 * in at build time and never fetched at runtime. The output is gitignored:
 * Contentful is the only source of truth.
 *
 *   node scripts/sync-translations.mjs
 *
 * Runs automatically before `dev` and `build` (see package.json). If
 * Contentful can't be reached, the files generated by the last successful
 * sync are reused (offline dev); if there are none, it exits with an error,
 * because the app can't compile without them.
 */
import { existsSync, readdirSync, rmSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const DIR = join(ROOT, "src/i18n/translations");
const CONTENT_TYPE = "translation";

try {
  process.loadEnvFile?.(join(ROOT, ".env"));
} catch {
  // No .env file: rely on the process environment (CI, Vercel).
}

const space = process.env.CONTENTFUL_SPACE_ID;
const token = process.env.CONTENTFUL_ACCESS_TOKEN;
const environment = process.env.CONTENTFUL_ENVIRONMENT || "master";
const log = (message) => console.info(`[translations] ${message}`);

// Builds run on Vercel/CI with this token, so it must be read-only. Personal
// access tokens (Management API, read/write) start with "CFPAT-".
if (token?.startsWith("CFPAT-")) {
  throw new Error("CONTENTFUL_ACCESS_TOKEN is a Contentful management (read/write) token. Use the read-only Delivery API token; management tokens belong only in local admin scripts.");
}

const sorted = (object) => Object.fromEntries(Object.entries(object).sort(([a], [b]) => a.localeCompare(b)));
const serialise = (object) => `${JSON.stringify(sorted(object), null, 2)}\n`;

async function cda(path) {
  const res = await fetch(`https://cdn.contentful.com/spaces/${space}/environments/${environment}${path}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  const body = await res.json();
  if (!res.ok) {throw new Error(`${res.status} ${body?.sys?.id ?? ""}: ${body?.message ?? ""}`);}
  return body;
}

async function fetchAll() {
  const locales = (await cda("/locales")).items;
  const defaultLocale = locales.find((l) => l.default)?.code ?? "en-US";
  const entries = [];
  for (let skip = 0; ; skip += 1000) {
    const page = await cda(`/entries?content_type=${CONTENT_TYPE}&locale=*&limit=1000&skip=${skip}&select=fields.key,fields.value`);
    entries.push(...page.items);
    if (entries.length >= page.total) {break;}
  }
  if (entries.length === 0) {throw new Error(`no "${CONTENT_TYPE}" entries (run \`yarn translations:push\`)`);}
  return { locales: locales.map((l) => l.code), defaultLocale, entries };
}

function writeIndex(locales) {
  const ident = (code) => code.replace(/[^a-zA-Z0-9]/g, "");
  const imports = locales.map((code) => `import ${ident(code)} from "./${code}.json";`).join("\n");
  const map = locales.map((code) => `  "${code}": ${ident(code)},`).join("\n");
  const source = `// Generated by scripts/sync-translations.mjs — one import per locale in Contentful.\n${imports}\n\nexport const DICTIONARIES = {\n${map}\n} as const;\n`;
  writeFileSync(join(DIR, "index.ts"), source);
}

/** Contentful values per locale; missing values fall back to the default locale at runtime. */
function buildDictionaries(remote) {
  const byLocale = Object.fromEntries(remote.locales.map((code) => [code, {}]));
  for (const entry of remote.entries) {
    const key = entry.fields.key?.[remote.defaultLocale];
    if (!key) {continue;}
    for (const [code, value] of Object.entries(entry.fields.value ?? {})) {
      if (typeof value === "string" && value.length > 0) {byLocale[code][key] = value;}
    }
  }
  return byLocale;
}

function writeDictionaries(locales, byLocale, entryCount) {
  mkdirSync(DIR, { recursive: true });
  for (const file of readdirSync(DIR).filter((f) => f.endsWith(".json"))) {
    if (!locales.includes(file.replace(/\.json$/, ""))) {rmSync(join(DIR, file));}
  }
  for (const code of locales) {writeFileSync(join(DIR, `${code}.json`), serialise(byLocale[code]));}
  writeIndex(locales);
  const counts = locales.map((code) => `${code} ${Object.keys(byLocale[code]).length}`).join(", ");
  log(`Synced ${entryCount} entries (${counts}).`);
}

async function main() {
  try {
    if (!space || !token) {throw new Error("CONTENTFUL_SPACE_ID / CONTENTFUL_ACCESS_TOKEN not set");}
    const remote = await fetchAll();
    writeDictionaries(remote.locales, buildDictionaries(remote), remote.entries.length);
  } catch (error) {
    if (existsSync(join(DIR, "index.ts"))) {
      log(`Contentful unavailable (${error.message}); reusing the last generated files.`);
      return;
    }
    console.error(`[translations] Can't generate translation files: ${error.message}`);
    process.exit(1);
  }
}

await main();
